# US release compares the long word whole, move.l ($b4).w,d7 / cmp.l
# #...,d7 at $1B76; the PAL release its two words, move.w $b4(a1),d1 /
# subi.w #...,d1 at $1992 and move.w $b6(a2),d1 / subi.w #...,d1 at $D800.
